// GBP collector draft v0.1 (2026-09-05). Builds a market_snapshots row for the
// GBP Layer 1 agent using repo-verified providers only. Unavailable fundamentals
// (UK 2Y, BoE bias, UK events, UK PMI, UK stress) are written null and listed in
// data_quality.missing - never proxied or guessed.

function num(v) {
  if (v === null || v === undefined || v === "." || v === "") return null;
  const cleaned = String(v).replace("%", "").replace(",", ".").trim();
  const n = Number(cleaned);
  return Number.isFinite(n) ? n : null;
}

function getNode(name) {
  try {
    return $(name).first().json;
  } catch (error) {
    return null;
  }
}

function getNodeAll(name) {
  try {
    return $(name).all().map((item) => item.json);
  } catch (error) {
    return [];
  }
}

function fredLatest(data) {
  const obs = (data && data.observations) || [];
  const valid = obs.filter((o) => num(o.value) !== null);
  const latest = num(valid[0] && valid[0].value);
  return {
    latest,
    d1: valid[1] && latest !== null ? latest - num(valid[1].value) : null,
    d5: valid[5] && latest !== null ? latest - num(valid[5].value) : null,
    d20: valid[20] && latest !== null ? latest - num(valid[20].value) : null,
    date: (valid[0] && valid[0].date) || null
  };
}

function fredPct(data) {
  const obs = (data && data.observations) || [];
  const valid = obs.filter((o) => num(o.value) !== null);
  const latest = num(valid[0] && valid[0].value);
  function pct(i) {
    const old = num(valid[i] && valid[i].value);
    if (latest === null || old === null || old === 0) return null;
    return ((latest - old) / old) * 100;
  }
  return {
    latest,
    d1: pct(1),
    d5: pct(5),
    d20: pct(20),
    date: (valid[0] && valid[0].date) || null
  };
}

function coinbasePrice(data) {
  return num(data && data.data && data.data.amount);
}

function bps(v) {
  return v === null || v === undefined ? null : v * 100;
}

function pctChange(current, old) {
  current = num(current);
  old = num(old);
  if (current === null || old === null || old === 0) return null;
  return ((current - old) / old) * 100;
}

const now = new Date();
const today = now.toISOString().slice(0, 10);

const previousRows = getNodeAll("Supabase | Get Previous Market Snapshots")
  .filter((r) => r.snapshot_date && r.run_time_et && r.snapshot_date < today)
  .sort((a, b) => new Date(b.run_time_et) - new Date(a.run_time_et));

const uniquePreviousRows = [];
const seenDates = new Set();
for (const row of previousRows) {
  if (!seenDates.has(row.snapshot_date)) {
    seenDates.add(row.snapshot_date);
    uniquePreviousRows.push(row);
  }
}

function historyPct(current, field, index) {
  const oldRow = uniquePreviousRows[index];
  return oldRow ? pctChange(current, oldRow[field]) : null;
}

const us2y = fredLatest(getNode("HTTP Request | US 2Y Treasury Yield - FRED API"));
const vix = fredLatest(getNode("HTTP Request | VIX - FRED Api"));
const dxy = fredPct(getNode("HTTP Request | DXY - FRED Dollar Index - FRED API"));
const uk10y = fredLatest(getNode("HTTP Request | UK 10Y Benchmark Yield - FRED api"));
const gbpusdPrice = coinbasePrice(getNode("HTTP Request | GBP/USD - Coinbase"));

// Global growth regime uses the shared snapshot NQ 20-day trend when enough NQ
// history exists in previous rows (same derivation as the EUR collector).

const missing = [];
function checkMissing(label, value) {
  if (value === null || value === undefined) missing.push(label);
}
checkMissing("vix_level", vix.latest);
checkMissing("dxy_level", dxy.latest);
checkMissing("us_2y_yield", us2y.latest);
checkMissing("gbpusd_price", gbpusdPrice);
// Unavailable by design (no repo-verified provider on 2026-09-05):
missing.push("uk_2y_yield (no verified UK 2Y daily provider)");
missing.push("uk_2y_d5_bps (depends on UK 2Y)");
missing.push("us_uk_2y_spread_d5_bps (depends on UK 2Y)");
missing.push("boe_bias (UK economic events coverage not available)");
missing.push("latest_uk_event (UK economic events coverage not available)");
missing.push("uk_composite_pmi / uk_composite_pmi_direction (no verified UK PMI source)");
missing.push("uk_stress_flag (no repo-verified UK stress proxy)");
missing.push("global_growth_regime (requires 20 shared NQ snapshot rows)");
missing.push("gbpusd_d1_pct (requires previous GBP snapshot row)");

const row = {
  snapshot_date: today,
  run_time_et: now.toISOString(),
  source_status: "partial",
  collector_version: "gbp_collector_draft_v0_1",

  vix_level: vix.latest,
  vix_d1: vix.d1,
  vix_d5: vix.d5,

  dxy_level: dxy.latest,
  dxy_d1: dxy.d1,
  dxy_d5: dxy.d5,
  dxy_d20: dxy.d20,

  us_2y_yield: us2y.latest,
  us_2y_d5_bps: bps(us2y.d5),
  us_2y_d20_bps: bps(us2y.d20),

  uk_10y_yield: uk10y.latest,
  uk_10y_d5_bps: bps(uk10y.d5),
  uk_10y_d20_bps: bps(uk10y.d20),

  uk_2y_yield: null,
  uk_2y_d5_bps: null,
  uk_2y_d20_bps: null,

  us_uk_2y_spread: null,
  us_uk_2y_spread_d5_bps: null,
  us_uk_2y_spread_d20_bps: null,

  gbpusd_price: gbpusdPrice,
  gbpusd_d1_pct: historyPct(gbpusdPrice, "gbpusd_price", 0),
  gbpusd_d5_pct: historyPct(gbpusdPrice, "gbpusd_price", 4),
  gbpusd_d20_pct: historyPct(gbpusdPrice, "gbpusd_price", 19),

  boe_bias: null,
  latest_uk_event: null,
  uk_composite_pmi: null,
  uk_composite_pmi_direction: null,
  uk_stress_flag: null,

  equities_regime: equitiesRegime,
  global_growth_regime: globalGrowthRegime,

  data_quality: {
    collector_status: "partial_by_design",
    missing,
    history_rows_used: uniquePreviousRows.length,
    notes: [
      "GBP collector draft v0.1; review-only, not deployed.",
      "FRED api_key values in this draft are placeholders; configure the real key outside the repository.",
      "dxy uses the repo's DTWEXBGS broad-dollar proxy; naming vs dxy_d1_pct is an open reconciliation item.",
      "UK 2Y / BoE bias / UK events / UK PMI / UK stress are unavailable until providers are approved."
    ]
  },

  raw_payload: {
    previous_snapshot_dates_used: uniquePreviousRows.map((r) => r.snapshot_date),
    us2y,
    vix,
    dxy,
    uk10y
  }
};

return [{ json: row }];

const nqRows = uniquePreviousRows.filter((r) => r.nq_price !== null && r.nq_price !== undefined);
let globalGrowthRegime = null;
if (nqRows.length >= 20) {
  const nq20dPct = pctChange(nqRows[0].nq_price, nqRows[19].nq_price);
  globalGrowthRegime = nq20dPct !== null ? (nq20dPct > 5 ? "expanding" : nq20dPct < -5 ? "contracting" : "neutral") : null;
}

const equitiesRegime =
  vix.latest !== null
    ? vix.latest < 16
      ? "risk_on"
      : vix.latest > 25
        ? "risk_off"
        : "neutral"
    : null;

// Fail closed: never insert a snapshot row that cannot support a GBP snapshot
// read (requires GBP/USD spot price plus identity timestamps).
const row = $input.first().json;

if (
  !row ||
  !row.snapshot_date ||
  !row.run_time_et ||
  row.gbpusd_price === null ||
  row.gbpusd_price === undefined
) {
  return [];
}

return [{ json: row }];
